-- 1700 opérations, catégorisées automatiquement selon votre dictionnaire de règles
-- À coller dans Supabase > SQL Editor > New query > Run
-- ======================================================================

with nouveaux_imports as (
  insert into imports (exercice_id, type_import, mois, nom_fichier, statut)
  select e.id, 'banque', v.mois, v.nom_fichier, 'importé'
  from (values
  ('2026-01', 'Relevé n°001 du 31-01-2026_CCOU 87005854626 EURL GEMVAP.pdf'),
  ('2026-02', 'Relevé n°002 du 28-02-2026_CCOU 87005854626 EURL GEMVAP.pdf'),
  ('2026-03', 'Relevé n°003 du 31-03-2026_CCOU 87005854626 EURL GEMVAP.pdf'),
  ('2026-04', 'Relevé n°004 du 30-04-2026_CCOU 87005854626 EURL GEMVAP.pdf'),
  ('2026-05', 'Relevé n°005 du 31-05-2026_CCOU 87005854626 EURL GEMVAP.pdf')
  ) as v(mois, nom_fichier)
  join exercices e on to_date(v.mois || '-01', 'YYYY-MM-DD') between e.date_debut and e.date_fin
  returning id, mois
)
insert into operations_bancaires (
  exercice_id, import_id, date_operation, libelle, debit, credit,
  categorie_proposee_id, affectation, mot_cle_reconnu, confiance, etat
)
